INSERT INTO `announcements_backup_20260322` (`id`, `title`, `content`, `publisher`, `publisher_role`, `publish_time`, `valid_from`, `valid_to`, `target_type`, `target_value`, `priority`, `attachments`, `status`, `create_time`, `update_time`) VALUES (84,'关于2025年春季实习安排的通知','各位同学：\n\n学院定于2025年3月1日开始春季实习，请各位同学提前做好准备。\n\n具体安排如下：\n1. 实习时间：2025年3月1日-6月30日\n2. 实习地点：各合作企业\n3. 实习要求：每周提交实习周记\n\n如有疑问，请联系学院办公室。','张教授','COLLEGE','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'important',NULL,'EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(85,'2025年优秀实习生评选通知','各位同学：\n\n学院将开展2025年优秀实习生评选活动，具体安排如下：\n\n评选条件：\n1. 实习期间表现优秀\n2. 实习单位评价良好\n3. 实习周记完整\n4. 无违纪记录\n\n评选时间：2025年7月\n请符合条件的同学积极申报。','刘院长','COLLEGE','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'important',NULL,'EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(86,'关于系统维护的通知','各位用户：\n\n系统将于2025年1月20日凌晨2:00-6:00进行维护升级，届时系统将暂停服务。\n\n请提前做好相关安排，给您带来的不便敬请谅解。\n\n维护内容：\n1. 系统性能优化\n2. 安全漏洞修复\n3. 新功能上线','系统管理员','ADMIN','2026-01-18 02:32:35','2026-01-17 18:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal','[{\"url\": \"/api/uploads/2026/01/28/c0a0c0e8-ea26-4bcb-a4aa-9c8944f5a095.pdf\", \"name\": \"@2011 团队作业结构的分类及其特征研究_任婧.pdf\", \"size\": 378639, \"type\": \"application/pdf\"}]','EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(87,'系部实习安全培训通知','各位同学：\n\n系部将于本周五下午2点在系会议室进行实习安全培训，请所有即将参加实习的同学务必参加。\n\n培训内容：\n1. 实习期间的安全注意事项\n2. 紧急情况处理方法\n3. 实习保险相关政策\n\n请准时参加，不得缺席。','李主任','DEPARTMENT','2026-01-18 02:32:35','2026-01-17 18:32:35',NULL,'TEACHER_TYPE',NULL,'normal','[{\"url\": \"/api/uploads/2026/01/28/2e9f1ed2-1b48-4262-8228-6467af0ebfe3.pdf\", \"name\": \"@2011 团队作业结构的分类及其特征研究_任婧.pdf\", \"size\": 378639, \"type\": \"application/pdf\"}]','EXPIRED','2026-01-18 02:32:34','2026-01-28 00:17:35'),(88,'关于实习期间考勤管理的通知','各位同学：\n\n为确保实习质量，现对实习期间的考勤管理做如下规定：\n\n1. 每日上下班需打卡\n2. 请假需提前3天申请\n3. 每月缺勤超过3天将影响实习成绩\n4. 实习结束后需提交考勤记录表\n\n请严格遵守考勤制度。','王辅导员','COUNSELOR','2026-01-18 02:32:35','2026-01-17 18:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal','[{\"url\": \"/api/uploads/2026/01/28/9409694e-6194-47c4-a2c2-1c8611d4bc85.docx\", \"name\": \"实习心得3.docx\", \"size\": 14411, \"type\": \"application/vnd.openxmlformats-officedocument.wordprocessingml.document\"}]','EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(89,'系部实习材料提交截止通知','各位同学：\n\n系部提醒各位同学，实习材料提交截止时间为2025年1月25日，请尚未提交的同学尽快完成。\n\n需要提交的材料：\n1. 实习协议书\n2. 企业接收函\n3. 实习周记\n4. 实习总结报告\n\n逾期将影响实习成绩。','陈主任','DEPARTMENT','2026-01-18 02:32:35','2026-01-17 18:32:35',NULL,'TEACHER_TYPE',NULL,'normal','[{\"url\": \"/api/uploads/2026/01/28/bc806b04-fc30-40d4-916a-b23fe01f8272.docx\", \"name\": \"实习心得3.docx\", \"size\": 14411, \"type\": \"application/vnd.openxmlformats-officedocument.wordprocessingml.document\"}]','EXPIRED','2026-01-18 02:32:34','2026-01-28 00:19:59'),(90,'关于实习期间心理健康关怀的通知','各位同学：\n\n实习期间可能会遇到各种压力和挑战，学院为大家提供心理咨询服务：\n\n服务内容：\n1. 个体心理咨询\n2. 团体心理辅导\n3. 心理健康讲座\n4. 24小时心理热线\n\n如有需要，请联系辅导员。','赵辅导员','COUNSELOR','2026-01-18 02:32:35','2026-01-17 18:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal','[{\"url\": \"/api/uploads/2026/01/28/1313d235-c1cd-41f7-885e-a12e3568eec8.pdf\", \"name\": \"@2011 团队作业结构的分类及其特征研究_任婧.pdf\", \"size\": 378639, \"type\": \"application/pdf\"}]','EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(91,'2025年春季实习招聘会通知','各位同学：\n\n学院将于2025年2月15日举办春季实习招聘会，届时将有50多家知名企业参加，提供超过500个实习岗位。请各位同学积极参与，做好简历准备。\n\n时间：2025年2月15日 9:00-17:00\n地点：学院体育馆\n\n请各班级做好组织工作。','就业指导中心','ADMIN','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal',NULL,'EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(92,'关于提交实习材料的重要通知','各位同学：\n\n请尚未提交实习相关材料的同学，务必在2025年1月25日前完成以下材料的提交：\n\n1. 实习申请表\n2. 实习协议书\n3. 企业接收函\n\n逾期未提交者将影响实习成绩评定。如有疑问，请联系各班辅导员。','教务处','ADMIN','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal',NULL,'EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(93,'实习安全教育培训通知','各位即将参加实习的同学：\n\n为确保实习期间的安全，学院将组织实习安全教育培训，具体安排如下：\n\n时间：2025年1月20日 14:00-16:00\n地点：学术报告厅\n内容：实习安全注意事项、应急处理方法等\n\n请所有即将参加实习的同学务必参加，不得缺席。','学生处','ADMIN','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal',NULL,'EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(94,'优秀实习生评选活动启动','各位同学：\n\n为表彰在实习中表现优秀的学生，学院决定开展\"优秀实习生\"评选活动。评选条件如下：\n\n1. 实习期间表现优秀，获得企业好评\n2. 实习报告质量高\n3. 积极参与学院实习相关活动\n\n申请截止时间：2025年2月28日\n评选结果将于3月15日公布。','就业指导中心','ADMIN','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal',NULL,'EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(95,'计算机学院实习双选会预告','计算机学院的同学们：\n\n专门针对计算机相关专业的实习双选会将于2025年1月30日举行，参会企业包括：\n\n- 腾讯科技\n- 阿里巴巴\n- 字节跳动\n- 华为技术\n- 百度在线\n\n等20余家知名IT企业。请计算机、软件工程、网络工程专业的同学积极参与。','计算机学院','ADMIN','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'MAJOR',NULL,'normal',NULL,'EXPIRED','2026-01-18 02:32:34','2026-01-18 02:32:34'),(96,'实习','实习报告提交要求：\n1. 字数不少于3000字\n2. 包含实习内容、收获和体会\n3. 格式规范，附实习证明\n\n提交截止日期：9月10日','管理员','ADMIN','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal',NULL,'EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(97,'实习安全注意事项','为确保实习期间的安全，请注意以下事项：\n1. 遵守企业规章制度\n2. 注意交通和人身安全\n3. 及时向指导老师汇报情况\n\n祝大家实习顺利！','管理员','ADMIN','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal',NULL,'EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(98,'2024年夏季实习安排通知','各位同学：\n\n2024年夏季实习安排已经确定，具体内容如下：\n1. 实习时间：7月1日 - 8月31日\n2. 实习要求：每周至少40小时\n3. 提交材料：实习报告、实习日志\n\n请各班级做好安排。','管理员','ADMIN','2026-01-18 02:32:35','2026-01-18 02:32:35',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal',NULL,'EXPIRED','2026-01-18 02:32:34','2026-03-14 19:44:45'),(101,'当前有效的公告','这是一个当前有效的公告，在有效期内','系统管理员','ADMIN','2026-01-15 10:00:00','2026-01-15 02:00:00','2026-01-24 10:00:00','[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'important','[]','DRAFT','2026-01-18 15:21:52','2026-03-14 19:44:45'),(102,'即将过期的公告','这是一个即将过期的公告，还有2天过期','系统管理员','ADMIN','2026-01-16 10:00:00','2026-01-16 02:00:00','2026-01-20 02:00:00','[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal','[{\"url\": \"/api/uploads/2026/01/28/5a0c7098-1796-4dca-bbe3-7e2107bda9ae.pdf\", \"name\": \"@2011 团队作业结构的分类及其特征研究_任婧.pdf\", \"size\": 378639, \"type\": \"application/pdf\"}]','EXPIRED','2026-01-18 15:21:52','2026-03-14 19:44:45'),(103,'未来生效的公告','这是一个未来才生效的公告','系统管理员','ADMIN','2026-01-18 10:00:00','2026-01-25 10:00:00','2026-02-10 10:00:00','[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal',NULL,'EXPIRED','2026-01-18 15:21:52','2026-03-16 01:00:00'),(104,'长期有效的公告','这是一个长期有效的公告，没有过期时间','系统管理员','ADMIN','2026-01-15 10:00:00','2026-01-15 02:00:00',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'important','[]','PUBLISHED','2026-01-18 15:21:52','2026-03-14 19:44:45'),(107,'测试','测试','管理员','ADMIN','2026-03-10 15:00:01','2026-03-10 07:00:01','2026-03-29 08:00:00','MAJOR','8','important','[{\"url\": \"https://lzj-java-ai.oss-cn-beijing.aliyuncs.com/images/2026/03/879f3c87-37e3-412a-a8ce-ff3ab61691c9.png\", \"name\": \"exported_image.png\", \"size\": 642144, \"type\": \"image/png\"}]','PUBLISHED','2026-03-10 15:00:01','2026-03-10 21:11:13'),(108,'测试','测试','某某某','ADMIN','2026-03-10 18:44:36','2026-03-10 18:44:36',NULL,'[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal','[{\"url\": \"https://lzj-java-ai.oss-cn-beijing.aliyuncs.com/images/2026/03/39d4a2ed-31fb-4e91-ac04-536cc840f8a1.png\", \"name\": \"exported_image (1).png\", \"size\": 712392, \"type\": \"image/png\"}]','PUBLISHED','2026-03-10 18:44:35','2026-03-14 19:44:45'),(109,'关于2025届毕业生实习安排的通知','各位同学：根据学校教学安排，2025届毕业生实习工作即将开始。请各位同学及时登录系统完善个人信息，并在规定时间内完成实习单位的选择和确认。具体安排如下：1. 实习时间：2025年3月-2025年6月；2. 实习形式：集中实习与自主实习相结合；3. 请各班级辅导员做好组织工作。','教务处','COLLEGE','2026-03-16 04:30:01','2026-03-16 04:30:01','2026-04-15 04:30:01','[\"STUDENT\",\"TEACHER\"]',NULL,'important',NULL,'PUBLISHED','2026-03-16 04:30:01','2026-03-16 04:30:01'),(110,'实习单位变更申请流程说明','各位同学：如需变更实习单位，请在系统中提交\"单位变更申请\"，并上传相关证明材料。申请将在3个工作日内审核完成。注意：实习开始后原则上不允许变更单位，确有特殊情况的需提供充分理由。','实习指导中心','DEPARTMENT','2026-03-16 04:30:01','2026-03-16 04:30:01','2026-03-31 04:30:01','[\"STUDENT\"]',NULL,'normal',NULL,'PUBLISHED','2026-03-16 04:30:01','2026-03-16 04:30:01'),(111,'关于考研学生延迟实习的通知','各位考研学生：根据学校政策，参加2025年全国硕士研究生招生考试的学生可申请延迟实习。请在系统中提交\"考研延迟申请\"，并上传准考证复印件。审核通过后，实习时间将调整至考试结束后。','学生处','COLLEGE','2026-03-14 04:30:01','2026-03-14 04:30:01','2026-05-15 04:30:01','[\"STUDENT\",\"TEACHER\"]',NULL,'important',NULL,'PUBLISHED','2026-03-16 04:30:01','2026-03-16 04:30:01'),(112,'实习期间安全注意事项','各位实习学生：实习期间请注意以下安全事项：1. 遵守实习单位的规章制度；2. 注意人身和财产安全；3. 遇到问题及时与指导老师或辅导员联系；4. 定期在系统中提交实习周报。祝大家实习顺利！','安全管理处','COLLEGE','2026-03-11 04:30:01','2026-03-11 04:30:01','2026-06-14 04:30:01','[\"STUDENT\"]',NULL,'normal',NULL,'PUBLISHED','2026-03-16 04:30:01','2026-03-16 04:30:01'),(113,'教师实习指导工作培训通知','各位实习指导教师：为提高实习指导质量，学院将于下周三下午2:00在会议室举行实习指导工作培训会。会议内容包括：1. 实习管理系统使用培训；2. 实习指导经验分享；3. 常见问题解答。请各位老师准时参加。','教学副院长','COLLEGE','2026-03-15 04:30:01','2026-03-15 04:30:01','2026-03-23 04:30:01','[\"TEACHER\"]',NULL,'normal',NULL,'PUBLISHED','2026-03-16 04:30:01','2026-03-16 04:30:01'),(114,'2024年春季实习安排通知','各位同学：\n\n根据学校教学计划安排，现将2024年春季学期实习相关事项通知如下：\n\n1. 实习时间：2024年3月1日至2024年6月30日\n2. 实习单位需提前在系统中完成资质审核\n3. 学生需在实习开始前一周完成实习申请\n4. 实习期间需按时提交周报和月报\n\n请各位同学认真阅读实习手册，按时完成各项任务。如有疑问，请联系辅导员或实习指导老师。\n\n教务处\n2024年2月15日','系统管理员','ADMIN','2026-03-16 04:37:56','2024-02-15 00:00:00','2024-06-30 23:59:59','[\"STUDENT\"]',NULL,'important','[{\"id\": \"att_001\", \"url\": \"https://example.com/files/manual.pdf\", \"name\": \"2024年春季实习手册.pdf\", \"size\": 2048576, \"type\": \"application/pdf\", \"uploadTime\": \"2024-02-15T10:00:00\"}]','EXPIRED','2026-03-16 04:37:56','2026-03-16 17:00:00'),(115,'关于实习安全注意事项的公告','各位实习学生：\n\n为确保实习期间的人身和财产安全，特提醒以下注意事项：\n\n1. 遵守实习单位的各项规章制度\n2. 注意上下班交通安全\n3. 保护个人隐私，不随意透露敏感信息\n4. 遇到问题及时向指导老师和家长汇报\n5. 保持通讯畅通，定期向学校汇报实习情况\n\n祝大家实习顺利！\n\n学生工作处\n2024年3月1日','张教师','COLLEGE','2026-03-16 04:38:27','2024-03-01 00:00:00','2024-07-31 23:59:59','[\"STUDENT\",\"TEACHER\"]',NULL,'normal','[]','EXPIRED','2026-03-16 04:38:27','2026-03-16 17:00:00'),(116,'实习报告提交截止时间提醒','各位同学：\n\n2024年春季学期实习报告提交截止时间为2024年7月15日，请尚未提交的同学抓紧时间完成并提交。\n\n提交要求：\n1. 报告格式按照模板要求\n2. 字数不少于3000字\n3. 需有实习单位盖章\n4. 电子版和纸质版均需提交\n\n逾期将影响实习成绩评定。\n\n教务处\n2024年6月20日','李教师','DEPARTMENT','2026-03-16 04:38:27','2024-06-20 00:00:00','2024-07-15 23:59:59','[\"STUDENT\"]',NULL,'important','[{\"id\": \"att_002\", \"url\": \"https://example.com/files/template.docx\", \"name\": \"实习报告模板.docx\", \"size\": 512000, \"type\": \"application/vnd.openxmlformats-officedocument.wordprocessingml.document\", \"uploadTime\": \"2024-06-20T09:00:00\"}]','EXPIRED','2026-03-16 04:38:27','2026-03-16 17:00:00'),(117,'新学期实习动员大会通知（草稿）','各位同学：\n\n学校将于近期召开2024年秋季学期实习动员大会，具体安排如下：\n\n时间：待定\n地点：待定\n参会人员：全体2021级学生\n\n会议内容：\n1. 实习政策解读\n2. 实习单位介绍\n3. 学生代表经验分享\n4. 现场答疑\n\n请各位同学提前安排好时间，准时参加。\n\n教务处\n2024年8月1日','王辅导员','COUNSELOR','2026-03-16 04:38:40','2024-09-01 00:00:00','2024-09-30 23:59:59','[\"STUDENT\"]',NULL,'normal','[]','DRAFT','2026-03-16 04:38:40','2026-03-16 04:38:40'),(118,'关于举办实习经验分享会的通知','各位师生：\n\n为帮助同学们更好地完成实习任务，学院拟举办实习经验分享会，邀请优秀实习生代表分享实习心得。\n\n时间：2024年4月15日 14:00\n地点：教学楼A301\n\n欢迎广大师生积极参加！\n\n计算机学院\n2024年4月10日','张教师','COLLEGE','2026-03-16 04:38:40','2024-04-10 00:00:00','2024-04-20 23:59:59','[\"ALL\"]',NULL,'normal','[]','EXPIRED','2026-03-16 04:38:40','2026-03-16 04:38:40'),(119,'9527','9527','某某某','ADMIN','2026-03-16 14:59:47','2026-03-16 14:59:24','2026-03-31 00:00:00','[\"STUDENT\",\"TEACHER\",\"COMPANY\"]',NULL,'normal','[]','PUBLISHED','2026-03-16 06:59:48','2026-03-16 06:59:48'),(120,'zz','zz','李老师','DEPARTMENT','2026-03-16 15:17:33','2026-03-16 15:17:23','2026-03-31 00:00:00','[\"STUDENT\"]',NULL,'important','[]','PUBLISHED','2026-03-16 07:17:34','2026-03-16 07:17:34'),(121,'实习系统使用说明','欢迎使用实习管理系统，请各位同学及时完善个人信息和实习状态登记。','系统管理员','ADMIN','2026-03-19 15:52:54',NULL,NULL,'STUDENT',NULL,'important',NULL,'PUBLISHED','2026-03-19 15:52:54','2026-03-19 15:52:54'),(122,'实习报告提交提醒','请已实习的同学在规定时间内提交实习周志和实习报告。','教务处','ADMIN','2026-03-19 15:52:54',NULL,NULL,'STUDENT',NULL,'normal',NULL,'PUBLISHED','2026-03-19 15:52:54','2026-03-19 15:52:54');
