INSERT INTO `internship_ai_analysis` (`id`, `student_id`, `overall_analysis`, `keywords`, `sentiment_positive`, `sentiment_neutral`, `sentiment_negative`, `suggested_attitude_score`, `suggested_performance_score`, `suggested_report_score`, `analysis_time`, `update_time`) VALUES (1,56,'该学生实习报告内容详实，结构清晰。从报告内容可以看出，学生在实习期间态度认真，能够主动学习新技术。报告中提到的技术栈与实际项目需求匹配度高，体现了较强的学习能力。建议在今后的学习中加强对底层原理的理解。','[\"Vue.js\", \"Element UI\", \"前端开发\", \"团队协作\", \"项目管理\"]',85,12,3,18,35,17,'2026-03-16 04:31:12','2026-03-16 04:31:12'),(3,58,'该学生实习报告体现了全栈开发的视野。报告内容全面，涵盖了前后端开发的多个方面。学生对技术栈的掌握较为均衡，具有良好的技术敏感度。建议在未来选择一至两个方向深入研究。','[\"全栈开发\", \"前后端联调\", \"RESTful API\", \"接口开发\", \"测试工作\"]',88,10,2,19,37,18,'2026-03-16 04:31:12','2026-03-16 04:31:12'),(4,59,'该学生实习报告展现了移动端开发的实践经验。报告内容详实，对跨平台开发技术有较深入的理解。学生在适配和性能优化方面有独到的见解。建议加强对原生开发技术的学习。','[\"uni-app\", \"跨平台开发\", \"移动端\", \"flex布局\", \"性能优化\"]',75,20,5,16,32,15,'2026-03-16 04:31:12','2026-03-16 04:31:12');
