INSERT INTO `problem_feedback` (`id`, `create_time`, `update_time`, `user_type`, `user_id`, `user_name`, `user_account`, `title`, `content`, `feedback_type`, `status`, `priority`, `attachment_url`, `admin_reply`, `admin_id`, `admin_name`, `reply_time`, `resolve_time`, `deleted`) VALUES (1,'2026-01-17 23:35:36','2026-01-18 02:01:53','student',1,'张三','20200101','系统登录页面加载缓慢','我在使用Chrome浏览器登录系统时，发现登录页面加载时间超过10秒，影响使用体验。希望能优化页面加载速度。','system','processing','low',NULL,NULL,NULL,NULL,NULL,NULL,0),(2,'2026-01-17 23:35:36','2026-01-18 02:01:53','student',2,'李四','20200102','建议添加实习日志导出功能','目前只能在线查看实习日志，希望能够支持导出为PDF或Excel格式，方便我们保存和打印。','feature','processing','low',NULL,NULL,NULL,NULL,NULL,NULL,0),(3,'2026-01-17 23:35:36','2026-01-18 02:01:53','student',3,'王五','20200103','作业提交后无法修改','我在提交作业后发现有个错误想要修改，但是系统提示已提交无法修改。希望增加修改功能。','bug','resolved','low',NULL,'您好，已收到您的反馈。作业提交后确实不支持修改，这是为了保证作业提交的严肃性。建议您在提交前仔细检查。如有特殊情况，请联系您的老师。',1,'系统管理员','2025-12-15 10:30:00',NULL,0),(4,'2026-01-17 23:35:36','2026-01-18 02:01:53','student',4,'赵六','20200104','实习单位信息显示不完整','我的实习单位信息中缺少联系电话和地址信息，导致无法联系企业。','data','processing','low',NULL,NULL,NULL,NULL,NULL,NULL,0),(5,'2026-01-17 23:35:36','2026-01-18 01:52:07','student',5,'孙七','20200105','建议增加消息提醒功能','希望系统能够在收到新消息或作业通知时，通过邮件或短信提醒我们，避免错过重要信息。','feature','processing','low',NULL,NULL,NULL,NULL,NULL,NULL,0),(6,'2026-01-17 23:35:36','2026-01-26 14:42:15','teacher',5,'李老师','002','学生实习数据统计不准确','在查看学生实习数据统计时，发现部分学生的实习时长计算有误，请尽快修复。','bug','resolved','normal',NULL,'好的，已解决',1,'admin','2026-01-26 14:42:15','2026-01-26 14:42:15',0),(7,'2026-01-17 23:35:36','2026-01-18 01:52:07','teacher',6,'张老师','001','建议增加批量评分功能','目前评分需要逐个学生进行操作，工作量较大。希望增加批量评分功能，提高工作效率。','feature','processing','normal',NULL,NULL,NULL,NULL,NULL,NULL,0),(8,'2026-01-17 23:35:36','2026-01-18 02:01:51','teacher',7,'王老师','003','课程资源上传失败','尝试上传课程资源时，系统提示\"文件大小超出限制\"，但文件只有5MB，应该符合要求。','system','resolved','normal',NULL,'您好，问题已修复。之前系统限制设置为2MB，现已调整为10MB。您可以重新上传文件。',2,'管理员','2025-12-14 14:20:00',NULL,0),(10,'2026-01-17 23:35:36','2026-01-24 16:58:22','company',2,'李四','阿里巴巴集团','建议增加招聘信息置顶功能','希望能够在发布招聘信息时选择置顶，让更多学生看到我们的招聘需求。','feature','resolved','high',NULL,'好的，没问题',1,'admin','2026-01-24 16:58:22','2026-01-24 16:58:22',0),(11,'2026-01-17 23:35:36','2026-01-18 01:56:45','company',3,'王五','字节跳动科技有限公司','实习评价表单无法提交','填写完学生实习评价后，点击提交按钮无反应，多次尝试均失败。','bug','closed','high',NULL,'您好，问题已解决。之前是网络波动导致的提交失败，现在系统已优化网络请求机制，可以正常提交了。',1,'admin','2026-01-18 01:56:45','2026-01-18 01:56:37',0),(12,'2026-01-17 23:35:36','2026-01-18 02:01:48','company',5,'孙七','华为技术有限公司','企业信息审核时间过长','我们提交的企业信息审核已经超过3天了，还没有结果，希望能加快审核速度。','other','processing','high',NULL,NULL,NULL,NULL,NULL,NULL,0),(13,'2026-01-17 23:35:36','2026-01-18 02:01:48','company',6,'李经理','北京科技有限公司','建议增加实习协议在线签署功能','目前实习协议需要线下签署，比较麻烦。希望增加在线签署功能，提高效率。','feature','closed','high',NULL,'测试',1,'admin','2026-01-18 01:57:01','2026-01-18 01:38:19',0),(14,'2026-03-16 04:29:42','2026-03-16 04:29:42','student',1,'张三','2021001001','实习单位信息有误','我的实习单位信息显示不正确，请帮忙核实修改','data_error','pending','high',NULL,NULL,NULL,NULL,NULL,NULL,0),(15,'2026-03-16 04:29:42','2026-03-16 04:29:42','student',2,'李四','2021001002','无法提交实习报告','系统提示报告格式不正确，但我已经按照要求填写','system_issue','pending','normal',NULL,NULL,NULL,NULL,NULL,NULL,0),(16,'2026-03-16 04:29:42','2026-03-16 04:29:42','student',3,'王五','2021001003','实习时间冲突','由于学校课程调整，需要修改实习开始时间','schedule_conflict','processing','high',NULL,NULL,NULL,NULL,NULL,NULL,0);
/*!40000 ALTER TABLE `problem_feedback` ENABLE KEYS */;
