INSERT INTO `resource_documents` (`id`, `title`, `description`, `file_url`, `file_name`, `file_type`, `file_size`, `publisher_id`, `publisher`, `publisher_role`, `publish_time`, `target_type`, `target_value`, `status`, `download_count`, `view_count`, `create_time`, `update_time`) VALUES (18,'实习管理系统使用指南','详细介绍实习管理系统的各项功能和使用方法，包括学生端、教师端、管理员端的操作说明。','/uploads/resource-documents/2025/01/24/guide.pdf','实习管理系统使用指南.pdf','application/pdf',2048576,1,'系统管理员','ADMIN','2025-01-15 09:30:00','ALL',NULL,'PUBLISHED',156,342,'2026-01-24 13:26:06','2026-01-24 13:26:06'),(19,'2025年实习工作安排通知','关于2025年学生实习工作的具体安排和要求，包括实习时间、实习单位选择、实习报告提交等事项。','/uploads/resource-documents/2025/01/20/notice.pdf','2025年实习工作安排通知.pdf','application/pdf',1572864,1,'系统管理员','ADMIN','2025-01-20 14:20:00','ALL',NULL,'PUBLISHED',89,234,'2026-01-24 13:26:06','2026-01-24 13:26:06'),(20,'实习安全规范手册','学生在实习期间必须遵守的安全规范和注意事项，确保实习过程安全有序。','/uploads/resource-documents/2025/01/18/safety.pdf','实习安全规范手册.pdf','application/pdf',3145728,1,'系统管理员','ADMIN','2025-01-18 10:00:00','ALL',NULL,'PUBLISHED',234,567,'2026-01-24 13:26:06','2026-01-24 13:26:06'),(21,'Java编程基础教程','Java编程语言的基础知识讲解，包括语法、面向对象编程、常用类库等内容。','/uploads/resource-documents/2025/01/10/java.pdf','Java编程基础教程.pdf','application/pdf',5242880,2,'张老师','TEACHER','2025-01-10 10:15:00','ALL',NULL,'PUBLISHED',312,678,'2026-01-24 13:26:06','2026-01-24 13:26:06'),(22,'数据库设计原理','数据库设计的理论基础和实践方法，包括ER图设计、范式理论、SQL优化等。','/uploads/resource-documents/2025/01/12/database.pdf','数据库设计原理.pdf','application/pdf',4194304,2,'张老师','TEACHER','2025-01-12 16:45:00','ALL',NULL,'PUBLISHED',198,423,'2026-01-24 13:26:06','2026-01-24 13:26:06'),(23,'Web前端开发实战','HTML、CSS、JavaScript等前端技术的实战教程，包含多个项目案例。','/uploads/resource-documents/2025/01/14/web.pdf','Web前端开发实战.pdf','application/pdf',6291456,3,'李老师','TEACHER','2025-01-14 11:30:00','ALL',NULL,'PUBLISHED',267,534,'2026-01-24 13:26:06','2026-01-24 13:26:06'),(24,'Python数据分析入门','使用Python进行数据分析的基础教程，包括NumPy、Pandas、Matplotlib等库的使用。','/uploads/resource-documents/2025